function format(s){return Math.floor(s/60).toString().padStart(2,'0')+':'+Math.floor(s%60).toString().padStart(2,'0')}
async function audio(){if(!ctx){ctx=new AudioContext();analyser=ctx.createAnalyser();analyser.fftSize=2048;analyser.smoothingTimeConstant=.75;bins=new Uint8Array(analyser.frequencyBinCount);wave=new Float32Array(analyser.fftSize);master=ctx.createGain();master.gain.value=.4;analyser.connect(master);master.connect(ctx.destination)}await ctx.resume()}
