function update(){$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'暂停':'播放');$('demo').classList.toggle('selected',mode==='demo');$('march').classList.toggle('selected',mode==='march');$('mic').classList.toggle('selected',mode==='mic');$('status').textContent=playing?'运行中 · '+(mode==='demo'?'演示信号':mode==='march'?'进行曲':mode==='mic'?'实时输入':'音频分析'):'待机 · '+(mode==='demo'?'演示预览':mode==='march'?'进行曲待命':'已暂停');$('tracksub').textContent=playing?'控制棒随频谱实时响应':'点击播放，启动声场';$('seek').disabled=mode!=='file';}
const MARCH_BPM=112,CHORDS=[[50,53,57],[50,53,57],[43,46,50],[45,49,52]],MEL=[74,0,0,0,77,0,0,0,81,0,79,0,77,0,0,0,76,0,0,0,74,0,0,0,72,0,74,0,76,0,0,0,77,0,0,0,79,0,0,0,81,0,79,0,77,0,0,0,76,0,73,0,76,0,0,0,81,0,81,0,81,0,0,0];
const mf=n=>440*Math.pow(2,(n-69)/12);
function mEnv(t,dur,peak){const v=ctx.createGain();v.gain.setValueAtTime(0,t);v.gain.linearRampToValueAtTime(peak,t+.014);v.gain.exponentialRampToValueAtTime(.0001,t+dur);return v}
function mTone(type,fr,t,dur,peak,det,dest){const o=ctx.createOscillator(),v=mEnv(t,dur,peak);o.type=type;o.frequency.value=fr;if(det)o.detune.value=det;o.connect(v);v.connect(dest||marchBus);o.start(t);o.stop(t+dur+.03);o.onended=()=>{try{o.disconnect();v.disconnect()}catch{}}}
function mBrass(t,notes,dur,type,cut,peak,det){const f=ctx.createBiquadFilter(),v=mEnv(t,dur,peak);f.type='lowpass';f.frequency.setValueAtTime(cut,t);f.Q.value=1.1;f.connect(v);v.connect(marchBus);for(const n of notes)for(const d of det){const o=ctx.createOscillator();o.type=type;o.frequency.value=mf(n);o.detune.value=d;o.connect(f);o.start(t);o.stop(t+dur+.03);o.onended=()=>{try{o.disconnect()}catch{}}}}
function mKick(t){const o=ctx.createOscillator(),v=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(145,t);o.frequency.exponentialRampToValueAtTime(42,t+.15);v.gain.setValueAtTime(.95,t);v.gain.exponentialRampToValueAtTime(.001,t+.28);o.connect(v);v.connect(marchBus);o.start(t);o.stop(t+.32);o.onended=()=>{try{o.disconnect();v.disconnect()}catch{}}}
function mNoise(){if(noise)return noise;noise=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate);const d=noise.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;return noise}
function mSnare(t,soft){const s=ctx.createBufferSource(),f=ctx.createBiquadFilter(),v=ctx.createGain();s.buffer=mNoise();f.type='bandpass';f.frequency.value=1800;f.Q.value=.8;v.gain.setValueAtTime(soft?.07:.22,t);v.gain.exponentialRampToValueAtTime(.001,t+(soft?.06:.16));s.connect(f);f.connect(v);v.connect(marchBus);s.start(t);s.stop(t+.22);s.onended=()=>{try{s.disconnect();f.disconnect();v.disconnect()}catch{}};mTone('triangle',190,t,.06,soft?.03:.09)}
function mStepEmit(i,t,spb){const s=i&15,ch=CHORDS[i>>4];if(s===0||s===8)mKick(t);if(s===4||s===12)mSnare(t,0);else if(s===14||s===15)mSnare(t,1);if(s===0||s===8){mTone('triangle',mf(ch[0]-12),t,spb*1.7,.24);mTone('sawtooth',mf(ch[0]-24),t,spb*1.5,.08)}if(s%4===2)mBrass(t,ch.map(n=>n+12),spb*.85,'sawtooth',2600,.07,[-7,7]);const m=MEL[i];if(m)mBrass(t,[m],spb*2.2,'square',3200,.085,[-5,5])}
