function startMarch(){marchBus=ctx.createGain();marchBus.gain.value=.9;marchBus.connect(analyser);demoNodes.push(marchBus);mStep=0;marchNext=ctx.currentTime+.1;mTick();marchTimer=setInterval(mTick,40)}
function stopMarch(){if(marchTimer){clearInterval(marchTimer);marchTimer=null}if(marchBus){try{marchBus.disconnect()}catch{};marchBus=null}}
async function start(){if(loading||playing)return;loading=true;const attempt=++session;try{await audio();if(attempt!==session)return;if(mode==='mic'){const id=++session;loading=true;$('message').textContent='等待麦克风授权…';const s=await navigator.mediaDevices.getUserMedia({audio:true});if(id!==session){s.getTracks().forEach(t=>t.stop());return}stream=s;source=ctx.createMediaStreamSource(s);source.connect(analyser);master.gain.value=0;$('message').textContent='正在监听麦克风；停止或切换输入即可关闭。'}else{master.gain.value=+$('volume').value/100;let msg='音频仅在本机处理，不会上传。';if(mode==='file'&&buffer){if(offset>=buffer.duration)offset=0;source=ctx.createBufferSource();source.buffer=buffer;source.connect(analyser);source.onended=()=>{stop();offset=0;$('seek').value=0;$('elapsed').textContent='00:00'};source.start(0,offset)}else if(mode==='march'){startMarch();msg='内置进行曲 · '+MARCH_BPM+' BPM · Web Audio 实时合成；想听原曲请用「导入音频文件」。'}else{[55,82.41,110,164.81,220,329.63,440,659.25].forEach((freq,i)=>{const osc=ctx.createOscillator(),v=ctx.createGain(),lfo=ctx.createOscillator(),lg=ctx.createGain();osc.type=i<3?'triangle':'sine';osc.frequency.value=freq;v.gain.value=.025;lfo.frequency.value=.22+i*.087;lg.gain.value=.023;lfo.connect(lg);lg.connect(v.gain);osc.connect(v);v.connect(analyser);osc.start();lfo.start();demoNodes.push(osc,lfo,v,lg)})}$('message').textContent=msg}started=ctx.currentTime;playing=true;update()}catch(e){stop();$('message').textContent=mode==='mic'?'无法访问麦克风，请检查浏览器权限，或导入音频。':'无法播放此音频，请尝试其他文件。'}finally{if(attempt===session||!playing)loading=false}}
$('play').onclick=()=>{if(playing){offset+=ctx.currentTime-started;stop()}else start()};
$('demo').onclick=()=>{stop();mode='demo';offset=0;buffer=null;$('trackname').textContent='РЕАКТОР / ВНУТР. СИГНАЛ';$('duration').textContent='ДРОН / LOOP';$('elapsed').textContent='00:00';$('seek').value=0;update();start()};
$('march').onclick=()=>{stop();mode='march';offset=0;buffer=null;$('trackname').textContent='МАРШ / СИНТЕЗ · '+MARCH_BPM+' BPM';$('duration').textContent='МАРШ / LOOP';$('elapsed').textContent='00:00';$('seek').value=0;update();start()};
$('mic').onclick=()=>{stop();mode='mic';offset=0;buffer=null;$('trackname').textContent='MIC / 麦克风输入';$('duration').textContent='LIVE';$('elapsed').textContent='00:00';update();start()};
$('upload').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;stop();const id=session;loading=true;$('message').textContent='正在读取音频…';try{await audio();const decoded=await ctx.decodeAudioData(await f.arrayBuffer());if(id!==session)return;buffer=decoded;mode='file';offset=0;$('trackname').textContent=f.name;$('duration').textContent=format(buffer.duration);$('elapsed').textContent='00:00';$('seek').value=0;update();loading=false;await start()}catch{$('message').textContent='无法读取该文件，请尝试 MP3 或 WAV 音频。'}finally{loading=false;e.target.value=''}};
$('seek').onchange=()=>{if(mode!=='file'||!buffer)return;const was=playing;stop();offset=+$('seek').value/100*buffer.duration;$('elapsed').textContent=format(offset);if(was)start()};
$('gain').oninput=e=>{gain=+e.target.value;$('gainval').textContent=gain.toFixed(1)+'×'};$('smooth').oninput=e=>{smoothing=+e.target.value/100;$('smoothval').textContent=e.target.value+'%'};$('volume').oninput=e=>{$('volumeval').textContent=e.target.value+'%';if(master&&mode!=='mic')master.gain.setTargetAtTime(+e.target.value/100,ctx.currentTime,.03)};
canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;angle+=(e.clientX-drag.x)*.006;tilt=Math.max(.25,Math.min(.85,tilt+(e.clientY-drag.y)*.002));drag={x:e.clientX,y:e.clientY}};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(1.5,zoom-e.deltaY*.001))},{passive:false});$('reset').onclick=()=>{angle=-.32;tilt=.58;zoom=1};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('message').textContent='当前浏览器不支持全屏。'}};document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'退出全屏 ↙':'全屏 ↗'});window.addEventListener('pagehide',stop);update();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_reactor_response',description:'Adjust the reactor audio visualizer sensitivity and motion smoothing.',inputSchema:{type:'object',properties:{sensitivity:{type:'number',minimum:.3,maximum:3},smoothing:{type:'number',minimum:0,maximum:95}},required:['sensitivity','smoothing'],additionalProperties:false},execute(input){if(!input||!Number.isFinite(input.sensitivity)||input.sensitivity<.3||input.sensitivity>3||!Number.isFinite(input.smoothing)||input.smoothing<0||input.smoothing>95)throw Error('Invalid response settings');$('gain').value=input.sensitivity;$('gain').dispatchEvent(new Event('input'));$('smooth').value=input.smoothing;$('smooth').dispatchEvent(new Event('input'));return{ sensitivity:gain,smoothing:smoothing*100}}})).catch(()=>{})}catch{}}
